import React from 'react';
import {
  Box,
  Chip,
  CircularProgress,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography
} from '@mui/material';
import { format } from 'date-fns';
import { StudentClassUpdate } from '../../types';

interface CalendarSyncPreviewTableProps {
  updates: StudentClassUpdate[];
  loading: boolean;
}

const renderEventDates = (eventIso?: string) => {
  if (!eventIso) return 'Unknown';
  return format(new Date(eventIso), 'MMM d, yyyy');
};

const CalendarSyncPreviewTable: React.FC<CalendarSyncPreviewTableProps> = ({ updates, loading }) => {
  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
        <CircularProgress size={32} />
      </Box>
    );
  }

  if (!updates.length) {
    return (
      <Paper variant="outlined" sx={{ p: 4, textAlign: 'center' }}>
        <Typography variant="subtitle1" fontWeight={600}>
          No matches yet
        </Typography>
        <Typography variant="body2" color="text.secondary">
          Run a calendar scan to preview proposed class updates.
        </Typography>
      </Paper>
    );
  }

  return (
    <TableContainer component={Paper} variant="outlined">
      <Table>
        <TableHead>
          <TableRow>
            <TableCell>Student</TableCell>
            <TableCell>Events Found</TableCell>
            <TableCell>Matched Dates</TableCell>
            <TableCell align="right">Proposed Total</TableCell>
            <TableCell align="right">Remaining After Apply</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {updates.map((update) => (
            <TableRow key={update.studentId}>
              <TableCell>
                <Typography variant="subtitle1" fontWeight={600}>
                  {update.studentName}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Currently attended {update.currentTotalAttended} / Remaining {update.currentRemainingClasses}
                </Typography>
              </TableCell>
              <TableCell>
                <Chip color="primary" label={`${update.matchedEvents.length} events`} size="small" />
              </TableCell>
              <TableCell>
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                  {update.matchedEvents.map((event) => (
                    <Chip
                      key={event.eventId}
                      label={renderEventDates(event.eventStart)}
                      variant="outlined"
                      size="small"
                    />
                  ))}
                </Box>
              </TableCell>
              <TableCell align="right">
                <Typography variant="body1" fontWeight={600}>
                  {update.proposedTotalAttended}
                </Typography>
              </TableCell>
              <TableCell align="right">
                <Typography
                  variant="body1"
                  fontWeight={600}
                  color={update.proposedRemainingClasses < 0 ? 'error.main' : 'text.primary'}
                >
                  {update.proposedRemainingClasses}
                </Typography>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
};

export default CalendarSyncPreviewTable;

