// Student interface
export interface Student {
  id: string;
  name: string;
  email?: string;
  phone?: string;
  notificationEmail: string;
  createdAt: Date;
  calendarTags?: string[];
  calendarMatchStrategy?: 'name' | 'keywords' | 'both';
}

// Purchase interface
export interface Purchase {
  id: string;
  studentId: string;
  classesPurchased: number;
  purchaseDate: Date;
  notes?: string;
}

// Attendance interface
export interface Attendance {
  id: string;
  studentId: string;
  attendanceDate: Date;
  timeIn: Date | null;
  timeOut: Date | null;
  className?: string | null;
  location?: string | null;
  coach?: string | null;
  notes?: string | null;
  calendarEventId?: string | null;
  calendarId?: string | null;
  source?: 'manual' | 'google' | 'import';
}

// Extended attendance interface with student details for display
export interface AttendanceWithStudentDetails extends Omit<Attendance, 'studentId'> {
  studentId: string;
  studentName: string;
  studentEmail?: string;
}

// User roles for authentication
export enum UserRole {
  Admin = 'admin',
  Student = 'student'
}

// User interface with role
export interface User {
  uid: string;
  email: string;
  displayName?: string;
  role: UserRole;
}

// Calculate remaining classes
export interface StudentWithClasses extends Student {
  remainingClasses: number;
  totalPurchased: number;
  totalAttended: number;
}

// Google Calendar Integration Types

// Google Calendar Event
export interface GoogleCalendarEvent {
  id: string;
  summary: string;
  start: {
    dateTime?: string;
    date?: string;
    timeZone?: string;
  };
  end: {
    dateTime?: string;
    date?: string;
    timeZone?: string;
  };
  description?: string;
  location?: string;
  attendees?: Array<{
    email: string;
    responseStatus?: string;
  }>;
  created?: string;
  updated?: string;
}

export interface CalendarEventWithContext extends GoogleCalendarEvent {
  calendarId: string;
  calendarSummary?: string;
}

export interface StudentCalendarMatchRule {
  studentId: string;
  keywords: string[];
  strategy: 'name' | 'keywords' | 'both';
}

export interface MatchedEventDetails {
  eventId: string;
  calendarId: string;
  calendarName?: string;
  eventSummary: string;
  eventStart: string;
  eventEnd?: string;
  matchedKeyword?: string;
}

export interface StudentClassUpdate {
  studentId: string;
  studentName: string;
  currentTotalAttended: number;
  currentRemainingClasses: number;
  proposedTotalAttended: number;
  proposedRemainingClasses: number;
  matchedEvents: MatchedEventDetails[];
}

export interface CalendarScanSummary {
  eventsProcessed: number;
  studentsUpdated: number;
  unmatchedEvents: CalendarEventWithContext[];
  updates: StudentClassUpdate[];
  scannedAt: Date;
}

// Available Class for Sign-up
export interface AvailableClass {
  id: string;
  name: string;
  description?: string;
  instructor: string;
  startTime: Date;
  endTime: Date;
  location: string;
  maxCapacity: number;
  currentEnrollment: number;
  cost: number;
  classType: string; // 'beginner', 'intermediate', 'advanced'
  recurring?: {
    frequency: 'daily' | 'weekly' | 'monthly';
    interval: number;
    endDate?: Date;
  };
  prerequisites?: string[];
  isAvailable: boolean;
  signupDeadline?: Date;
}

// User Calendar Preferences
export interface CalendarPreferences {
  userId: string;
  googleCalendarId?: string;
  autoSignupEnabled: boolean;
  preferredClassTypes: string[];
  preferredTimes: {
    startTime: string; // HH:MM format
    endTime: string;   // HH:MM format
    daysOfWeek: number[]; // 0=Sunday, 1=Monday, etc.
  }[];
  maxClassesPerWeek: number;
  excludeDates: Date[];
  minimumNoticeHours: number; // Minimum hours before class to sign up
  conflictResolution: 'skip' | 'ask' | 'replace';
  notifications: {
    signupSuccess: boolean;
    signupFailed: boolean;
    conflictDetected: boolean;
    classReminder: boolean;
  };
  createdAt: Date;
  updatedAt: Date;
}

// Calendar Sync Status
export interface CalendarSyncStatus {
  userId: string;
  lastSyncTime: Date;
  syncEnabled: boolean;
  syncErrors: Array<{
    timestamp: Date;
    error: string;
    context?: string;
  }>;
  eventsSynced: number;
  calendarId: string;
}

// Class Signup Result
export interface ClassSignupResult {
  id: string;
  userId: string;
  classId: string;
  signupTime: Date;
  status: 'success' | 'failed' | 'waitlist' | 'cancelled';
  errorMessage?: string;
  calendarEventId?: string; // Google Calendar event ID if added to calendar
  autoSignup: boolean;
  notificationSent: boolean;
}

// Calendar Conflict
export interface CalendarConflict {
  classId: string;
  className: string;
  classTime: {
    start: Date;
    end: Date;
  };
  conflictingEvent: {
    id: string;
    title: string;
    start: Date;
    end: Date;
    calendar: string;
  };
  severity: 'full' | 'partial'; // full = complete overlap, partial = some overlap
  resolution?: 'ignore' | 'skip_class' | 'modify_event';
}

// Enhanced User interface with Google integration
export interface UserWithGoogleIntegration extends User {
  googleAccessToken?: string;
  googleRefreshToken?: string;
  googleCalendarConnected: boolean;
  calendarPreferences?: CalendarPreferences;
  lastCalendarSync?: Date;
} 