import { gapi } from 'gapi-script';
import { GoogleCalendarEvent, AvailableClass, CalendarConflict } from '../types';

// Google API configuration
const CLIENT_ID = process.env.REACT_APP_GOOGLE_CLIENT_ID;
const API_KEY = process.env.REACT_APP_GOOGLE_API_KEY;
const DISCOVERY_DOC = process.env.REACT_APP_GOOGLE_DISCOVERY_DOC;
const SCOPES = process.env.REACT_APP_GOOGLE_SCOPES || 'https://www.googleapis.com/auth/calendar';

class GoogleCalendarService {
  private isInitialized = false;
  private authInstance: any = null;

  // Initialize Google API
  async initialize(): Promise<void> {
    if (this.isInitialized) return;

    try {
      await new Promise<void>((resolve, reject) => {
        gapi.load('client:auth2', async () => {
          try {
            await gapi.client.init({
              apiKey: API_KEY,
              clientId: CLIENT_ID,
              discoveryDocs: [DISCOVERY_DOC!],
              scope: SCOPES
            });

            this.authInstance = gapi.auth2.getAuthInstance();
            this.isInitialized = true;
            console.log('Google Calendar API initialized successfully');
            resolve();
          } catch (error) {
            console.error('Error initializing Google API:', error);
            reject(error);
          }
        });
      });
    } catch (error) {
      console.error('Failed to load Google API:', error);
      throw new Error('Failed to initialize Google Calendar API');
    }
  }

  // Check if user is signed in
  isSignedIn(): boolean {
    return this.authInstance?.isSignedIn.get() || false;
  }

  // Get current user's email
  getCurrentUserEmail(): string | null {
    if (!this.isSignedIn()) return null;
    const user = this.authInstance?.currentUser.get();
    return user?.getBasicProfile().getEmail() || null;
  }

  // Sign in to Google
  async signIn(): Promise<any> {
    if (!this.authInstance) {
      throw new Error('Google API not initialized');
    }

    try {
      // Check if already signed in
      if (this.authInstance.isSignedIn.get()) {
        console.log('User already signed in');
        return this.authInstance.currentUser.get();
      }

      // Sign in with improved options
      const user = await this.authInstance.signIn({
        prompt: 'select_account'
      });
      console.log('Successfully signed in to Google:', user.getBasicProfile().getEmail());
      return user;
    } catch (error) {
      console.error('Google sign-in failed:', error);

      // More specific error handling
      if (error && (error as any).error === 'popup_closed_by_user') {
        throw new Error('Sign-in cancelled. Please try again and complete the Google sign-in process.');
      } else if (error && (error as any).error === 'access_denied') {
        throw new Error('Access denied. Please grant calendar permissions to use this feature.');
      } else {
        throw new Error('Failed to sign in to Google. Please try again.');
      }
    }
  }

  // Sign out from Google
  async signOut(): Promise<void> {
    if (!this.authInstance) {
      throw new Error('Google API not initialized');
    }

    try {
      await this.authInstance.signOut();
      console.log('Successfully signed out from Google');
    } catch (error) {
      console.error('Google sign-out failed:', error);
      throw new Error('Failed to sign out from Google');
    }
  }

  // Get user's calendar list
  async getCalendarList(): Promise<any[]> {
    if (!this.isSignedIn()) {
      throw new Error('User not signed in to Google');
    }

    try {
      const response = await gapi.client.calendar.calendarList.list({
        minAccessRole: 'writer'
      });
      return response.result.items || [];
    } catch (error) {
      console.error('Error fetching calendar list:', error);
      throw new Error('Failed to fetch calendar list');
    }
  }

  // Get events from primary calendar
  async getCalendarEvents(
    timeMin?: Date,
    timeMax?: Date,
    calendarId = 'primary'
  ): Promise<GoogleCalendarEvent[]> {
    if (!this.isSignedIn()) {
      throw new Error('User not signed in to Google');
    }

    try {
      const now = new Date();
      const startTime = timeMin || now;
      const endTime = timeMax || new Date(now.getTime() + (30 * 24 * 60 * 60 * 1000)); // 30 days

      const response = await gapi.client.calendar.events.list({
        calendarId,
        timeMin: startTime.toISOString(),
        timeMax: endTime.toISOString(),
        showDeleted: false,
        singleEvents: true,
        orderBy: 'startTime'
      });

      const events = response.result.items || [];
      
      return events.map((event: any): GoogleCalendarEvent => ({
        id: event.id,
        summary: event.summary || 'No title',
        start: {
          dateTime: event.start?.dateTime,
          date: event.start?.date,
          timeZone: event.start?.timeZone
        },
        end: {
          dateTime: event.end?.dateTime,
          date: event.end?.date,
          timeZone: event.end?.timeZone
        },
        description: event.description,
        location: event.location,
        attendees: event.attendees,
        created: event.created,
        updated: event.updated
      }));
    } catch (error) {
      console.error('Error fetching calendar events:', error);
      throw new Error('Failed to fetch calendar events');
    }
  }

  // Create a new calendar event
  async createCalendarEvent(
    classInfo: AvailableClass,
    calendarId = 'primary'
  ): Promise<string> {
    if (!this.isSignedIn()) {
      throw new Error('User not signed in to Google');
    }

    try {
      const event = {
        summary: `Badminton Class: ${classInfo.name}`,
        description: `${classInfo.description || ''}\n\nInstructor: ${classInfo.instructor}\nClass Type: ${classInfo.classType}\nCost: $${classInfo.cost}`,
        location: classInfo.location,
        start: {
          dateTime: classInfo.startTime.toISOString(),
          timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
        },
        end: {
          dateTime: classInfo.endTime.toISOString(),
          timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
        },
        reminders: {
          useDefault: false,
          overrides: [
            { method: 'email', minutes: 24 * 60 }, // 1 day before
            { method: 'popup', minutes: 30 }       // 30 minutes before
          ]
        }
      };

      const response = await gapi.client.calendar.events.insert({
        calendarId,
        resource: event
      });

      console.log('Calendar event created:', response.result.id);
      return response.result.id!;
    } catch (error) {
      console.error('Error creating calendar event:', error);
      throw new Error('Failed to create calendar event');
    }
  }

  // Update an existing calendar event
  async updateCalendarEvent(
    eventId: string,
    updates: Partial<GoogleCalendarEvent>,
    calendarId = 'primary'
  ): Promise<void> {
    if (!this.isSignedIn()) {
      throw new Error('User not signed in to Google');
    }

    try {
      await gapi.client.calendar.events.patch({
        calendarId,
        eventId,
        resource: updates
      });
      console.log('Calendar event updated:', eventId);
    } catch (error) {
      console.error('Error updating calendar event:', error);
      throw new Error('Failed to update calendar event');
    }
  }

  // Delete a calendar event
  async deleteCalendarEvent(
    eventId: string,
    calendarId = 'primary'
  ): Promise<void> {
    if (!this.isSignedIn()) {
      throw new Error('User not signed in to Google');
    }

    try {
      await gapi.client.calendar.events.delete({
        calendarId,
        eventId
      });
      console.log('Calendar event deleted:', eventId);
    } catch (error) {
      console.error('Error deleting calendar event:', error);
      throw new Error('Failed to delete calendar event');
    }
  }

  // Check for conflicts between a class and existing calendar events
  async checkForConflicts(
    classInfo: AvailableClass,
    calendarId = 'primary'
  ): Promise<CalendarConflict[]> {
    const conflicts: CalendarConflict[] = [];

    try {
      const events = await this.getCalendarEvents(
        new Date(classInfo.startTime.getTime() - 60 * 60 * 1000), // 1 hour before
        new Date(classInfo.endTime.getTime() + 60 * 60 * 1000),   // 1 hour after
        calendarId
      );

      for (const event of events) {
        const eventStart = new Date(event.start.dateTime || event.start.date!);
        const eventEnd = new Date(event.end.dateTime || event.end.date!);

        // Check for overlap
        const hasOverlap = (
          (classInfo.startTime < eventEnd && classInfo.endTime > eventStart)
        );

        if (hasOverlap) {
          // Determine severity of conflict
          const fullOverlap = (
            classInfo.startTime >= eventStart && classInfo.endTime <= eventEnd
          ) || (
            eventStart >= classInfo.startTime && eventEnd <= classInfo.endTime
          );

          conflicts.push({
            classId: classInfo.id,
            className: classInfo.name,
            classTime: {
              start: classInfo.startTime,
              end: classInfo.endTime
            },
            conflictingEvent: {
              id: event.id,
              title: event.summary,
              start: eventStart,
              end: eventEnd,
              calendar: calendarId
            },
            severity: fullOverlap ? 'full' : 'partial'
          });
        }
      }

      return conflicts;
    } catch (error) {
      console.error('Error checking for conflicts:', error);
      throw new Error('Failed to check for calendar conflicts');
    }
  }

  // Get access token for backend operations
  getAccessToken(): string | null {
    if (!this.isSignedIn()) return null;
    const user = this.authInstance?.currentUser.get();
    return user?.getAuthResponse().access_token || null;
  }

  // Refresh access token
  async refreshToken(): Promise<string | null> {
    if (!this.isSignedIn()) return null;
    
    try {
      const user = this.authInstance?.currentUser.get();
      await user?.reloadAuthResponse();
      return user?.getAuthResponse().access_token || null;
    } catch (error) {
      console.error('Error refreshing token:', error);
      return null;
    }
  }
}

// Export singleton instance
export const googleCalendarService = new GoogleCalendarService();
export default googleCalendarService;