import React, { useEffect, useState } from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  TextField,
  Typography
} from '@mui/material';
import { StudentWithClasses } from '../../types';

interface MatchingRulesDialogProps {
  open: boolean;
  onClose: () => void;
  students: StudentWithClasses[];
  matchingRules: Record<string, string[]>;
  onSave: (updatedRules: Record<string, string[]>) => void;
}

const MatchingRulesDialog: React.FC<MatchingRulesDialogProps> = ({
  open,
  onClose,
  students,
  matchingRules,
  onSave
}) => {
  const [localRules, setLocalRules] = useState<Record<string, string[]>>({});

  useEffect(() => {
    if (open) {
      setLocalRules(matchingRules);
    }
  }, [matchingRules, open]);

  const handleChange = (studentId: string, value: string) => {
    const entries = value
      .split(',')
      .map((rule) => rule.trim())
      .filter(Boolean);

    setLocalRules((prev) => ({
      ...prev,
      [studentId]: entries
    }));
  };

  const handleSave = () => {
    onSave(localRules);
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle>Custom Matching Keywords</DialogTitle>
      <DialogContent dividers>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Provide comma-separated keywords or nicknames for each student. These keywords will be matched against event
          titles and descriptions in addition to the student&apos;s full name.
        </Typography>

        <Box sx={{ maxHeight: 420, overflowY: 'auto', pr: 1 }}>
          <Grid container spacing={2}>
            {students.map((student) => (
              <Grid item xs={12} sm={6} key={student.id}>
                <TextField
                  fullWidth
                  label={student.name}
                  placeholder="e.g. Alice, Ally, Coach's Favorite"
                  value={(localRules[student.id] || []).join(', ')}
                  onChange={(event) => handleChange(student.id, event.target.value)}
                  helperText="Use commas to separate multiple keywords"
                />
              </Grid>
            ))}
          </Grid>
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} variant="text">
          Cancel
        </Button>
        <Button onClick={handleSave} variant="contained">
          Save Keywords
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default MatchingRulesDialog;

