import React, { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Typography,
  Alert,
  CircularProgress,
  Chip,
  Stack,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Switch,
  FormControlLabel,
  Divider
} from '@mui/material';
import {
  Google as GoogleIcon,
  CalendarMonth as CalendarIcon,
  CheckCircle as CheckIcon,
  Error as ErrorIcon,
  Sync as SyncIcon,
  Settings as SettingsIcon,
  Event as EventIcon
} from '@mui/icons-material';
import { useAuth } from '../contexts/AuthContext';
import googleCalendarService from '../services/googleCalendarService';
import { GoogleCalendarEvent } from '../types';
import { format } from 'date-fns';

const GoogleCalendarSync: React.FC = () => {
  const { 
    currentUser, 
    isGoogleCalendarConnected, 
    connectGoogleCalendar, 
    disconnectGoogleCalendar,
    calendarPreferences,
    updateCalendarPreferences
  } = useAuth();

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [events, setEvents] = useState<GoogleCalendarEvent[]>([]);
  const [showEvents, setShowEvents] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  // Clear messages after 5 seconds
  useEffect(() => {
    if (error || success) {
      const timer = setTimeout(() => {
        setError(null);
        setSuccess(null);
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [error, success]);

  const handleConnectCalendar = async () => {
    setLoading(true);
    setError(null);
    setSuccess(null);

    try {
      await connectGoogleCalendar();
      setSuccess('Google Calendar connected successfully!');
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to connect Google Calendar';
      console.error('Calendar connection error:', err);

      // Provide specific guidance for common errors
      if (errorMessage.includes('cancelled') || errorMessage.includes('popup_closed_by_user')) {
        setError('Sign-in was cancelled. Please click "Connect Google Calendar" again and complete the sign-in process.');
      } else if (errorMessage.includes('blocked')) {
        setError('Popup was blocked. Please allow popups for this site and try again.');
      } else {
        setError(errorMessage);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleDisconnectCalendar = async () => {
    setLoading(true);
    setError(null);
    
    try {
      await disconnectGoogleCalendar();
      setEvents([]);
      setSuccess('Google Calendar disconnected successfully!');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to disconnect Google Calendar');
    } finally {
      setLoading(false);
    }
  };

  const handleSyncEvents = async () => {
    if (!isGoogleCalendarConnected) {
      setError('Please connect your Google Calendar first');
      return;
    }

    setLoading(true);
    setError(null);
    
    try {
      const startDate = new Date();
      const endDate = new Date();
      endDate.setDate(startDate.getDate() + 30); // Next 30 days
      
      const calendarEvents = await googleCalendarService.getCalendarEvents(startDate, endDate);
      setEvents(calendarEvents);
      setShowEvents(true);
      setSuccess(`Synchronized ${calendarEvents.length} events from your calendar!`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to sync calendar events');
    } finally {
      setLoading(false);
    }
  };

  const handleToggleAutoSignup = async (enabled: boolean) => {
    try {
      await updateCalendarPreferences({
        autoSignupEnabled: enabled
      });
      setSuccess(`Auto sign-up ${enabled ? 'enabled' : 'disabled'} successfully!`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update preferences');
    }
  };

  const formatEventTime = (event: GoogleCalendarEvent) => {
    if (event.start.dateTime) {
      return format(new Date(event.start.dateTime), 'MMM d, yyyy h:mm a');
    } else if (event.start.date) {
      return format(new Date(event.start.date), 'MMM d, yyyy');
    }
    return 'Unknown time';
  };

  if (!currentUser) {
    return null;
  }

  return (
    <Card sx={{ maxWidth: 600, margin: 'auto' }}>
      <CardContent>
        <Box display="flex" alignItems="center" mb={2}>
          <GoogleIcon sx={{ mr: 1, color: '#4285f4' }} />
          <Typography variant="h6">
            Google Calendar Integration
          </Typography>
          {isGoogleCalendarConnected && (
            <Chip
              icon={<CheckIcon />}
              label="Connected"
              color="success"
              size="small"
              sx={{ ml: 2 }}
            />
          )}
        </Box>

        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}

        {success && (
          <Alert severity="success" sx={{ mb: 2 }}>
            {success}
          </Alert>
        )}

        <Stack spacing={2}>
          {!isGoogleCalendarConnected ? (
            <Box>
              <Typography variant="body2" color="text.secondary" mb={2}>
                Connect your Google Calendar to sync events and enable automatic class sign-ups.
              </Typography>
              <Button
                variant="contained"
                startIcon={<GoogleIcon />}
                onClick={handleConnectCalendar}
                disabled={loading}
                sx={{
                  bgcolor: '#4285f4',
                  '&:hover': { bgcolor: '#3367d6' }
                }}
              >
                {loading ? <CircularProgress size={20} /> : 'Connect Google Calendar'}
              </Button>
            </Box>
          ) : (
            <Box>
              <Typography variant="body2" color="text.secondary" mb={2}>
                Your Google Calendar is connected. You can now sync events and manage auto sign-up preferences.
              </Typography>
              
              <Stack direction="row" spacing={2} mb={2}>
                <Button
                  variant="outlined"
                  startIcon={<SyncIcon />}
                  onClick={handleSyncEvents}
                  disabled={loading}
                >
                  Sync Events
                </Button>
                
                <Button
                  variant="outlined"
                  startIcon={<SettingsIcon />}
                  onClick={() => setShowSettings(true)}
                >
                  Settings
                </Button>
                
                <Button
                  variant="outlined"
                  color="error"
                  onClick={handleDisconnectCalendar}
                  disabled={loading}
                >
                  Disconnect
                </Button>
              </Stack>

              {events.length > 0 && (
                <Box>
                  <Typography variant="subtitle2" mb={1}>
                    Recent Events: {events.length} events found
                  </Typography>
                  <Button
                    variant="text"
                    startIcon={<EventIcon />}
                    onClick={() => setShowEvents(true)}
                    size="small"
                  >
                    View Events
                  </Button>
                </Box>
              )}

              {calendarPreferences && (
                <Box mt={2} p={2} bgcolor="action.hover" borderRadius={1}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={calendarPreferences.autoSignupEnabled}
                        onChange={(e) => handleToggleAutoSignup(e.target.checked)}
                      />
                    }
                    label="Enable automatic class sign-ups"
                  />
                  <Typography variant="caption" display="block" color="text.secondary">
                    Automatically sign up for classes based on your preferences
                  </Typography>
                </Box>
              )}
            </Box>
          )}
        </Stack>
      </CardContent>

      {/* Events Dialog */}
      <Dialog open={showEvents} onClose={() => setShowEvents(false)} maxWidth="md" fullWidth>
        <DialogTitle>
          <Box display="flex" alignItems="center">
            <CalendarIcon sx={{ mr: 1 }} />
            Calendar Events (Next 30 Days)
          </Box>
        </DialogTitle>
        <DialogContent>
          <List>
            {events.map((event, index) => (
              <React.Fragment key={event.id}>
                <ListItem>
                  <ListItemIcon>
                    <EventIcon />
                  </ListItemIcon>
                  <ListItemText
                    primary={event.summary || 'Untitled Event'}
                    secondary={
                      <Box>
                        <Typography variant="body2" color="text.secondary">
                          {formatEventTime(event)}
                        </Typography>
                        {event.location && (
                          <Typography variant="caption" display="block">
                            📍 {event.location}
                          </Typography>
                        )}
                        {event.description && (
                          <Typography variant="caption" display="block" sx={{ mt: 0.5 }}>
                            {event.description.slice(0, 100)}
                            {event.description.length > 100 && '...'}
                          </Typography>
                        )}
                      </Box>
                    }
                  />
                </ListItem>
                {index < events.length - 1 && <Divider />}
              </React.Fragment>
            ))}
          </List>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setShowEvents(false)}>Close</Button>
        </DialogActions>
      </Dialog>

      {/* Settings Dialog */}
      <Dialog open={showSettings} onClose={() => setShowSettings(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Calendar Preferences</DialogTitle>
        <DialogContent>
          <Stack spacing={2}>
            <FormControlLabel
              control={
                <Switch
                  checked={calendarPreferences?.autoSignupEnabled || false}
                  onChange={(e) => handleToggleAutoSignup(e.target.checked)}
                />
              }
              label="Enable automatic class sign-ups"
            />
            
            <Typography variant="body2" color="text.secondary">
              More preferences will be added here:
            </Typography>
            
            <List dense>
              <ListItem>
                <ListItemText 
                  primary="Preferred class types" 
                  secondary="Beginner, Intermediate, Advanced"
                />
              </ListItem>
              <ListItem>
                <ListItemText 
                  primary="Maximum classes per week" 
                  secondary={calendarPreferences?.maxClassesPerWeek || 3}
                />
              </ListItem>
              <ListItem>
                <ListItemText 
                  primary="Conflict resolution" 
                  secondary={calendarPreferences?.conflictResolution || 'Ask'}
                />
              </ListItem>
            </List>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setShowSettings(false)}>Close</Button>
        </DialogActions>
      </Dialog>
    </Card>
  );
};

export default GoogleCalendarSync;