import { CalendarEventWithContext, MatchedEventDetails, StudentClassUpdate, StudentWithClasses } from '../types';
import { getAttendanceByCalendarEventId, recordAttendance } from './studentService';

export interface MatchEventsOptions {
  events: CalendarEventWithContext[];
  students: StudentWithClasses[];
  matchingRules: Record<string, string[]>;
}

export interface MatchEventsResult {
  updates: StudentClassUpdate[];
  unmatchedEvents: CalendarEventWithContext[];
}

export interface ApplyUpdatesResult {
  createdCount: number;
  skippedCount: number;
  errors: Array<{ eventId: string; reason: string }>;
}

const DEFAULT_TIME_FALLBACK = 'T09:00:00';

const normalize = (value: string) => value.trim().toLowerCase();

const uniqueKeywords = (keywords: string[]) => {
  const seen = new Set<string>();
  const result: string[] = [];
  keywords.forEach((keyword) => {
    const normalized = normalize(keyword);
    if (!normalized || seen.has(normalized)) {
      return;
    }
    seen.add(normalized);
    result.push(keyword);
  });
  return result;
};

const buildKeywords = (
  student: StudentWithClasses,
  matchingRules: Record<string, string[]>
): string[] => {
  const strategy = student.calendarMatchStrategy || 'both';
  const manualRules = matchingRules[student.id] || [];
  const studentTags = student.calendarTags || [];

  const keywords: string[] = [];

  if (strategy === 'name' || strategy === 'both') {
    keywords.push(student.name);
  }

  if (strategy === 'keywords' || strategy === 'both') {
    keywords.push(...studentTags);
  }

  keywords.push(...manualRules);

  return uniqueKeywords(
    keywords
      .map((keyword) => keyword.trim())
      .filter((keyword) => keyword.length > 0)
  );
};

const buildEventText = (event: CalendarEventWithContext) => {
  const parts = [
    event.summary || '',
    event.description || '',
    event.location || '',
    event.attendees?.map((attendee) => attendee.email).join(' ') || ''
  ];
  return normalize(parts.join(' '));
};

const buildMatchedEventDetails = (
  event: CalendarEventWithContext,
  matchedKeyword?: string
): MatchedEventDetails => ({
  eventId: event.id,
  calendarId: event.calendarId,
  calendarName: event.calendarSummary,
  eventSummary: event.summary,
  eventStart: event.start.dateTime || event.start.date || '',
  eventEnd: event.end?.dateTime || event.end?.date,
  matchedKeyword
});

export const matchEventsToStudents = ({
  events,
  students,
  matchingRules
}: MatchEventsOptions): MatchEventsResult => {
  const updatesByStudentId = new Map<string, StudentClassUpdate>();
  const unmatchedEvents: CalendarEventWithContext[] = [];

  events.forEach((event) => {
    const eventText = buildEventText(event);
    const matchedStudents: Array<{ student: StudentWithClasses; keyword?: string }> = [];

    students.forEach((student) => {
      const keywords = buildKeywords(student, matchingRules);

      for (const keyword of keywords) {
        if (!keyword) continue;
        if (eventText.includes(normalize(keyword))) {
          matchedStudents.push({ student, keyword });
          break;
        }
      }
    });

    if (matchedStudents.length === 0) {
      unmatchedEvents.push(event);
      return;
    }

    matchedStudents.forEach(({ student, keyword }) => {
      const existing = updatesByStudentId.get(student.id);
      const matchDetails = buildMatchedEventDetails(event, keyword);

      if (!existing) {
        updatesByStudentId.set(student.id, {
          studentId: student.id,
          studentName: student.name,
          currentTotalAttended: student.totalAttended,
          currentRemainingClasses: student.remainingClasses,
          proposedTotalAttended: student.totalAttended + 1,
          proposedRemainingClasses: student.remainingClasses - 1,
          matchedEvents: [matchDetails]
        });
      } else {
        existing.matchedEvents.push(matchDetails);
        existing.proposedTotalAttended = existing.currentTotalAttended + existing.matchedEvents.length;
        existing.proposedRemainingClasses =
          existing.currentRemainingClasses - existing.matchedEvents.length;
      }
    });
  });

  return {
    updates: Array.from(updatesByStudentId.values()),
    unmatchedEvents
  };
};

const parseEventDate = (eventStart?: string): Date => {
  if (!eventStart) {
    return new Date();
  }

  if (eventStart.includes('T')) {
    return new Date(eventStart);
  }

  return new Date(`${eventStart}${DEFAULT_TIME_FALLBACK}`);
};

export const applyStudentClassUpdates = async (
  updates: StudentClassUpdate[]
): Promise<ApplyUpdatesResult> => {
  const result: ApplyUpdatesResult = {
    createdCount: 0,
    skippedCount: 0,
    errors: []
  };

  for (const update of updates) {
    for (const eventDetails of update.matchedEvents) {
      try {
        if (!eventDetails.eventId) {
          result.skippedCount += 1;
          continue;
        }

        const existingAttendance = await getAttendanceByCalendarEventId(eventDetails.eventId);
        if (existingAttendance) {
          result.skippedCount += 1;
          continue;
        }

        const attendanceDate = parseEventDate(eventDetails.eventStart);

        await recordAttendance({
          studentId: update.studentId,
          attendanceDate,
          timeIn: attendanceDate,
          timeOut: null,
          className: eventDetails.eventSummary || 'Synced Class',
          location: eventDetails.calendarName || undefined,
          notes: `Synced from Google Calendar${eventDetails.matchedKeyword ? ` • matched "${eventDetails.matchedKeyword}"` : ''}`,
          coach: undefined,
          calendarEventId: eventDetails.eventId,
          calendarId: eventDetails.calendarId,
          source: 'google'
        });

        result.createdCount += 1;
      } catch (error) {
        console.error('Failed to apply calendar event', eventDetails.eventId, error);
        result.errors.push({
          eventId: eventDetails.eventId,
          reason: error instanceof Error ? error.message : 'Unknown error'
        });
      }
    }
  }

  return result;
};

