import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { 
  User as FirebaseUser,
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  signOut, 
  onAuthStateChanged,
  sendPasswordResetEmail
} from 'firebase/auth';
import { doc, getDoc, setDoc, updateDoc } from 'firebase/firestore';
import { auth, db } from '../services/firebase';
import { User, UserRole, UserWithGoogleIntegration, CalendarPreferences } from '../types';
import googleCalendarService from '../services/googleCalendarService';

interface AuthContextType {
  currentUser: UserWithGoogleIntegration | null;
  userRole: UserRole | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string, name: string, role: UserRole) => Promise<void>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<void>;
  // Google Calendar integration
  isGoogleCalendarConnected: boolean;
  connectGoogleCalendar: () => Promise<void>;
  disconnectGoogleCalendar: () => Promise<void>;
  initializeGoogleCalendar: () => Promise<void>;
  // Calendar preferences
  calendarPreferences: CalendarPreferences | null;
  updateCalendarPreferences: (preferences: Partial<CalendarPreferences>) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

interface AuthProviderProps {
  children: ReactNode;
}

export function AuthProvider({ children }: AuthProviderProps) {
  const [currentUser, setCurrentUser] = useState<UserWithGoogleIntegration | null>(null);
  const [loading, setLoading] = useState(true);
  const [calendarPreferences, setCalendarPreferences] = useState<CalendarPreferences | null>(null);
  const [isGoogleCalendarConnected, setIsGoogleCalendarConnected] = useState(false);

  async function getUserData(firebaseUser: FirebaseUser): Promise<UserWithGoogleIntegration | null> {
    try {
      const userDocRef = doc(db, 'users', firebaseUser.uid);
      const userDoc = await getDoc(userDocRef);
      
      if (userDoc.exists()) {
        const data = userDoc.data();
        return {
          uid: firebaseUser.uid,
          email: firebaseUser.email || '',
          displayName: firebaseUser.displayName || data.displayName || '',
          role: data.role as UserRole,
          googleCalendarConnected: data.googleCalendarConnected || false,
          googleAccessToken: data.googleAccessToken,
          googleRefreshToken: data.googleRefreshToken,
          calendarPreferences: data.calendarPreferences,
          lastCalendarSync: data.lastCalendarSync ? data.lastCalendarSync.toDate() : undefined
        };
      } else {
        // If user document doesn't exist in Firestore, create a basic one
        // This is a fallback for cases where auth exists but Firestore data doesn't
        console.log('User document missing in Firestore. Creating basic profile...');
        try {
          const basicUserData = {
            email: firebaseUser.email || '',
            displayName: firebaseUser.displayName || '',
            role: UserRole.Student, // Default role
            createdAt: new Date()
          };
          
          // Create the user document
          await setDoc(userDocRef, basicUserData);
        } catch (firestoreError) {
          console.warn('Cannot create Firestore profile due to permission issue:', firestoreError);
          console.warn('This is expected if you haven\'t updated Firestore security rules.');
        }
        
        // Return a user object even if Firestore writing failed
        return {
          uid: firebaseUser.uid,
          email: firebaseUser.email || '',
          displayName: firebaseUser.displayName || '',
          role: UserRole.Student,
          googleCalendarConnected: false,
          googleAccessToken: undefined,
          googleRefreshToken: undefined,
          calendarPreferences: undefined,
          lastCalendarSync: undefined
        };
      }
    } catch (error) {
      console.error('Error fetching/creating user data:', error);
      
      // If it's a permission error, return a user object anyway
      // This allows the app to function even with Firestore permission issues
      console.log('Using fallback user data due to Firestore access issue');
      
      return {
        uid: firebaseUser.uid,
        email: firebaseUser.email || '',
        displayName: firebaseUser.displayName || '',
        role: UserRole.Student, // Default to Student role
        googleCalendarConnected: false,
        googleAccessToken: undefined,
        googleRefreshToken: undefined,
        calendarPreferences: undefined,
        lastCalendarSync: undefined
      };
    }
  }

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      try {
        if (firebaseUser) {
          const userData = await getUserData(firebaseUser);
          setCurrentUser(userData);
        } else {
          setCurrentUser(null);
        }
      } catch (error) {
        console.error('Auth state change error:', error);
        setCurrentUser(null);
      } finally {
        setLoading(false);
      }
    });

    return unsubscribe;
  }, []);

  async function login(email: string, password: string) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const userData = await getUserData(userCredential.user);
      setCurrentUser(userData);
    } catch (error) {
      console.error('Login error:', error);
      throw error;
    }
  }

  async function register(email: string, password: string, name: string, role: UserRole) {
    try {
      // Create the user in Firebase Authentication
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      
      try {
        // Try to create user document in Firestore
        await setDoc(doc(db, 'users', userCredential.user.uid), {
          email,
          displayName: name,
          role,
          createdAt: new Date()
        });
      } catch (firestoreError) {
        // If Firestore permission error, log it but continue
        console.warn('Firestore permission error. User created in Auth but not in Firestore:', firestoreError);
        console.warn('Please update your Firestore security rules in the Firebase Console.');
        
        // Show instructions in the console for updating security rules
        console.info(`
To fix this error, go to Firebase Console → Firestore Database → Rules and update with:

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /{document=**} {
      allow read, write: if request.auth != null;
    }
  }
}

This will temporarily allow all authenticated users to read/write. For production, use more restrictive rules.
        `);
      }
      
      // Set the user in state even if Firestore failed
      const userData: UserWithGoogleIntegration = {
        uid: userCredential.user.uid,
        email,
        displayName: name,
        role,
        googleCalendarConnected: false,
        googleAccessToken: undefined,
        googleRefreshToken: undefined,
        calendarPreferences: undefined,
        lastCalendarSync: undefined
      };
      
      setCurrentUser(userData);
      
      // Return success to the UI
      return;
    } catch (error) {
      console.error('Registration error:', error);
      throw error;
    }
  }

  async function logout() {
    try {
      await signOut(auth);
      setCurrentUser(null);
    } catch (error) {
      console.error('Logout error:', error);
      throw error;
    }
  }

  async function resetPassword(email: string) {
    return sendPasswordResetEmail(auth, email);
  }

  // Initialize Google Calendar API
  async function initializeGoogleCalendar(): Promise<void> {
    try {
      await googleCalendarService.initialize();
      console.log('Google Calendar API initialized');
    } catch (error) {
      console.error('Failed to initialize Google Calendar API:', error);
      throw error;
    }
  }

  // Connect Google Calendar
  async function connectGoogleCalendar(): Promise<void> {
    if (!currentUser) {
      throw new Error('User not authenticated');
    }

    try {
      await googleCalendarService.initialize();
      const googleUser = await googleCalendarService.signIn();
      
      // Get access token
      const accessToken = googleCalendarService.getAccessToken();
      
      if (!accessToken) {
        throw new Error('Failed to get Google access token');
      }

      // Update user data in Firestore
      const userDocRef = doc(db, 'users', currentUser.uid);
      await updateDoc(userDocRef, {
        googleCalendarConnected: true,
        googleAccessToken: accessToken,
        lastCalendarSync: new Date()
      });

      // Update local state
      setCurrentUser({
        ...currentUser,
        googleCalendarConnected: true,
        googleAccessToken: accessToken,
        lastCalendarSync: new Date()
      });

      setIsGoogleCalendarConnected(true);
      console.log('Google Calendar connected successfully');
    } catch (error) {
      console.error('Failed to connect Google Calendar:', error);
      throw error;
    }
  }

  // Disconnect Google Calendar
  async function disconnectGoogleCalendar(): Promise<void> {
    if (!currentUser) {
      throw new Error('User not authenticated');
    }

    try {
      await googleCalendarService.signOut();

      // Update user data in Firestore
      const userDocRef = doc(db, 'users', currentUser.uid);
      await updateDoc(userDocRef, {
        googleCalendarConnected: false,
        googleAccessToken: null,
        googleRefreshToken: null,
        lastCalendarSync: null
      });

      // Update local state
      setCurrentUser({
        ...currentUser,
        googleCalendarConnected: false,
        googleAccessToken: undefined,
        googleRefreshToken: undefined,
        lastCalendarSync: undefined
      });

      setIsGoogleCalendarConnected(false);
      console.log('Google Calendar disconnected successfully');
    } catch (error) {
      console.error('Failed to disconnect Google Calendar:', error);
      throw error;
    }
  }

  // Update calendar preferences
  async function updateCalendarPreferences(preferences: Partial<CalendarPreferences>): Promise<void> {
    if (!currentUser) {
      throw new Error('User not authenticated');
    }

    try {
      const updatedPreferences: CalendarPreferences = {
        userId: currentUser.uid,
        autoSignupEnabled: false,
        preferredClassTypes: [],
        preferredTimes: [],
        maxClassesPerWeek: 3,
        excludeDates: [],
        minimumNoticeHours: 2,
        conflictResolution: 'ask',
        notifications: {
          signupSuccess: true,
          signupFailed: true,
          conflictDetected: true,
          classReminder: true
        },
        createdAt: new Date(),
        updatedAt: new Date(),
        ...calendarPreferences,
        ...preferences
      };

      // Update in Firestore
      const userDocRef = doc(db, 'users', currentUser.uid);
      await updateDoc(userDocRef, {
        calendarPreferences: updatedPreferences
      });

      // Update local state
      setCalendarPreferences(updatedPreferences);
      setCurrentUser({
        ...currentUser,
        calendarPreferences: updatedPreferences
      });

      console.log('Calendar preferences updated successfully');
    } catch (error) {
      console.error('Failed to update calendar preferences:', error);
      throw error;
    }
  }

  // Initialize Google Calendar on auth state change
  useEffect(() => {
    if (currentUser) {
      initializeGoogleCalendar().catch(console.error);
      setIsGoogleCalendarConnected(currentUser.googleCalendarConnected || false);
      setCalendarPreferences(currentUser.calendarPreferences || null);
    }
  }, [currentUser]);

  const value = {
    currentUser,
    userRole: currentUser?.role || null,
    loading,
    login,
    register,
    logout,
    resetPassword,
    // Google Calendar integration
    isGoogleCalendarConnected,
    connectGoogleCalendar,
    disconnectGoogleCalendar,
    initializeGoogleCalendar,
    // Calendar preferences
    calendarPreferences,
    updateCalendarPreferences
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
} 